insert into notifications (id,workspace_id,user_id,type,title,body,entity_type,entity_id,read_at,created_by) select 'notification-'||i,case (i-1)%3 when 0 then 'ws-atlas' when 1 then 'ws-polaris' else 'ws-lantern' end,case (i-1)%3 when 0 then '10000000-0000-4000-8000-000000000001' when 1 then '10000000-0000-4000-8000-000000000002' else '10000000-0000-4000-8000-000000000003' end,case i%4 when 0 then 'deadline' when 1 then 'assignment' when 2 then 'stage_change' else 'mention' end,'Signal notification '||i,'A record needs attention','opportunity','opportunity-'||i,case when i%3=0 then '2026-09-01T08:00:00Z' else null end,case (i-1)%3 when 0 then '10000000-0000-4000-8000-000000000001' when 1 then '10000000-0000-4000-8000-000000000002' else '10000000-0000-4000-8000-000000000003' end from n;
insert into audit_events (id,workspace_id,action,entity_type,entity_id,summary,before_data,after_data,actor_id,created_by) select 'audit-'||i,case (i-1)%3 when 0 then 'ws-atlas' when 1 then 'ws-polaris' else 'ws-lantern' end,case i%4 when 0 then 'created' when 1 then 'updated' when 2 then 'stage_changed' else 'assigned' end,'opportunity','opportunity-'||(((i-1)%150)+1),'Opportunity activity '||i,'{"status":"open"}','{"status":"open","reviewed":true}',case (i-1)%3 when 0 then '10000000-0000-4000-8000-000000000001' when 1 then '10000000-0000-4000-8000-000000000002' else '10000000-0000-4000-8000-000000000003' end,case (i-1)%3 when 0 then '10000000-0000-4000-8000-000000000001' when 1 then '10000000-0000-4000-8000-000000000002' else '10000000-0000-4000-8000-000000000003' end from n;
